            Text="Mr.T Xem thay đổi trước khi ghi DWG";Font=UiStyle.Body();AutoScaleMode=AutoScaleMode.Dpi;Size=new Size(1260,790);MinimumSize=new Size(1060,720);StartPosition=FormStartPosition.CenterParent;
