            var grid=new DataGridView{Name="BatchReviewGrid",Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=false,AllowUserToAddRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};UiStyle.Grid(grid);foreach(var s in new[]{new[]{"LayerBefore","Layer cũ"},new[]{"LayerAfter","Layer mới"},new[]{"TypeAfter","Linetype sau"},new[]{"TextBefore","Chữ cũ"},new[]{"TextAfter","Chữ mới"},new[]{"ColorAfter","Màu sau"},new[]{"Detail","Chi tiết / lỗi"}})grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=s[0],HeaderText=s[1],MinimumWidth=s[0]=="Detail"?220:100});grid.DataSource=rows;root.Controls.Add(grid,0,1);
            var details=new TextBox{Name="BatchReviewDetails",Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Dock=DockStyle.Fill,WordWrap=false};Action update=delegate{var row=grid.CurrentRow==null?null:grid.CurrentRow.DataBoundItem as BatchPreviewRow;details.Text=row==null?"":row.LayerBefore+" → "+row.LayerAfter+"\r\nNét: "+row.TypeBefore+" → "+row.TypeAfter+"\r\nMàu Layer: "+row.ColorBefore+" → "+row.ColorAfter+"\r\nTRƯỚC: "+row.BeforeState+"\r\nSAU: "+row.AfterState+"\r\n"+row.Detail;};grid.SelectionChanged+=delegate{update();};Shown+=delegate{update();foreach(DataGridViewRow line in grid.Rows)if(((BatchPreviewRow)line.DataBoundItem).Blocked)line.DefaultCellStyle.ForeColor=Color.Firebrick;};root.Controls.Add(details,0,2);
            var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var apply=new Button{Name="ApplyBatch",Text=canApply?"Áp dụng "+rows.Count+" dòng":"Cần sửa dòng báo lỗi",Enabled=canApply,AutoSize=true,DialogResult=DialogResult.OK};var cancel=new Button{Name="CancelBatchReview",Text="Quay lại / Hủy",AutoSize=true,DialogResult=DialogResult.Cancel};buttons.Controls.Add(apply);buttons.Controls.Add(cancel);root.Controls.Add(buttons,0,3);AcceptButton=apply;CancelButton=cancel;
